41	        // Frequency-correct: use the CPU's actual clock period for the
42	        // cycles->ticks conversion (C0 2GHz=500t/cyc, C2-KP 2.6GHz~385t/cyc).
43	        // The old *1000 assumed 1GHz and never opened the window on C2.
44	        if (!cpu) return false;
