56	        // §2.6 FSU opClass filter: all scalar Float* + SIMD FP.
57	        return oc == FloatAddOp || oc == FloatCmpOp || oc == FloatCvtOp ||
58	               oc == FloatMultOp || oc == FloatMultAccOp || oc == FloatDivOp ||
59	               oc == FloatMiscOp || oc == FloatSqrtOp ||
60	               oc == SimdFloatAddOp || oc == SimdFloatAluOp || oc == SimdFloatCmpOp ||
61	               oc == SimdFloatCvtOp || oc == SimdFloatMultOp || oc == SimdFloatMultAccOp ||
62	               oc == SimdFloatDivOp || oc == SimdFloatSqrtOp || oc == SimdFloatMiscOp;
63	    }
